#include <linux/perf_event.h>
#include <linux/cpu.h>
#include <linux/slab.h>
#include <linux/workqueue.h>
#include <linux/coresight.h>

struct auxtrace_data {
    struct coresight_sink *sink;
    struct auxtrace_path *paths;
    struct work_struct free_work;
};

void *setup_aux_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite)
{
    struct auxtrace_data *data;
    struct coresight_device *csdev;
    struct coresight_sink *sink = NULL;
    struct coresight_source *src;
    struct auxtrace_path *path;
    int cpu;

    data = kmalloc(sizeof(*data), GFP_KERNEL);
    if (!data)
        return NULL;

    list_for_each_entry(csdev, &coresight_bus, entry) {
        if (csdev->type == CORESIGHT_DEV_TYPE_SINK) {
            sink = to_coresight_sink(csdev);
            if (sink->alloc_buffer(sink, nr_pages))
                break;
        }
    }

    if (!sink) {
        kfree(data);
        return NULL;
    }

    data->sink = sink;
    INIT_WORK(&data->free_work, NULL);

    data->paths = kcalloc(num_possible_cpus(), sizeof(*path), GFP_KERNEL);
    if (!data->paths) {
        kfree(data);
        return NULL;
    }

    for_each_possible_cpu(cpu) {
        src = coresight_get_source_for_cpu(cpu);
        if (!src) {
            kfree(data->paths);
            kfree(data);
            return NULL;
        }

        path = &data->paths[cpu];
        path->source = src;
        if (src->setup_path(src, event_cpu, overwrite)) {
            kfree(data->paths);
            kfree(data);
            return NULL;
        }
    }

    return data;
}

void *setup_aux_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite) {
    struct aux_event_data *event_data;
    struct coresight_device *sink;
    int cpu;

    event_data = kzalloc(sizeof(*event_data), GFP_KERNEL);
    if (!event_data)
        return NULL;

    sink = coresight_first_sink();
    if (!sink || !sink->ops->alloc_buffer) {
        kfree(event_data);
        return NULL;
    }

    event_data->sink = sink;
    event_data->pages = pages;
    event_data->nr_pages = nr_pages;
    event_data->overwrite = overwrite;

    INIT_WORK(&event_data->free_work, free_event_data_work);

    for_each_cpu(cpu, event_data->cpumask) {
        struct aux_event_path *path;

        path = kzalloc(sizeof(*path), GFP_KERNEL);
        if (!path) {
            cleanup_event_data(event_data);
            return NULL;
        }

        path->cpu = cpu;
        path->event_data = event_data;
        list_add(&path->list, &event_data->paths);
    }

    if (sink->ops->alloc_buffer(sink, event_data, pages, nr_pages, overwrite)) {
        cleanup_event_data(event_data);
        return NULL;
    }

    return event_data;
}

void *setup_aux_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite) {
    struct aux_event_data *event_data;
    struct coresight_sink *sink;
    int i;

    event_data = kmalloc(sizeof(struct aux_event_data), GFP_KERNEL);
    if (!event_data)
        return NULL;

    sink = coresight_get_enabled_sink();
    if (!sink || !sink->alloc_buffer) {
        kfree(event_data);
        return NULL;
    }

    event_data->sink = sink;
    event_data->cpu = event_cpu;
    event_data->pages = pages;
    event_data->nr_pages = nr_pages;
    event_data->overwrite = overwrite;

    INIT_WORK(&event_data->free_work, free_event_data_work);

    for (i = 0; i < nr_pages; i++) {
        if (!pages[i]) {
            cleanup_event_data(event_data);
            return NULL;
        }
    }

    if (sink->setup_paths(event_data) < 0) {
        cleanup_event_data(event_data);
        return NULL;
    }

    return event_data;
}

void *setup_aux_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite) {
    struct aux_event_data *event_data;
    struct coresight_device *sink;
    int cpu;

    event_data = kzalloc(sizeof(*event_data), GFP_KERNEL);
    if (!event_data)
        return NULL;

    sink = coresight_find_device_by_type(CORESINK, 0);
    if (!sink || !sink->alloc_buffer) {
        kfree(event_data);
        return NULL;
    }

    event_data->sink = sink;
    INIT_WORK(&event_data->free_work, free_event_data_work);

    for_each_possible_cpu(cpu) {
        struct aux_event_path *path;

        path = kzalloc(sizeof(*path), GFP_KERNEL);
        if (!path) {
            cleanup_paths(event_data);
            kfree(event_data);
            return NULL;
        }

        path->cpu = cpu;
        path->pages = pages;
        path->nr_pages = nr_pages;
        path->overwrite = overwrite;

        if (sink->alloc_buffer(sink, path)) {
            kfree(path);
            cleanup_paths(event_data);
            kfree(event_data);
            return NULL;
        }

        list_add(&path->list, &event_data->paths);
    }

    return event_data;
}

#include <linux/perf_event.h>
#include <linux/slab.h>
#include <linux/coresight.h>
#include <linux/workqueue.h>
#include <linux/cpu.h>

struct aux_event_data {
    struct coresight_device *sink;
    struct perf_cpu *paths;
    struct work_struct free_work;
};

void *setup_aux_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite)
{
    struct aux_event_data *event_data;
    struct coresight_device *sink = NULL;
    struct coresight_device *dev;
    struct coresight_path *path;
    int cpu, ret;

    event_data = kmalloc(sizeof(*event_data), GFP_KERNEL);
    if (!event_data)
        return NULL;

    list_for_each_entry(dev, &coresight_bus, entry) {
        if (dev->type == CORESIGHT_DEV_TYPE_SINK && dev->enable) {
            sink = dev;
            break;
        }
    }

    if (!sink || !sink->alloc_buffer) {
        kfree(event_data);
        return NULL;
    }

    ret = sink->alloc_buffer(sink, pages, nr_pages, overwrite);
    if (ret) {
        kfree(event_data);
        return NULL;
    }

    path = kcalloc(num_present_cpus, sizeof(*path), GFP_KERNEL);
    if (!path) {
        sink->free_buffer(sink, pages, nr_pages);
        kfree(event_data);
        return NULL;
    }

    for_each_present_cpu(cpu)
        path[cpu].cpu = cpu;

    event_data->sink = sink;
    event_data->paths = path;
    INIT_WORK(&event_data->free_work, NULL);

    return event_data;
}
